/* highlights.js — الإضاءات الرسمية («إضاءات نحو تحقيق المؤشر») بلغتين. العربية مصحّحة من ملف الهيئة (2026) (استُخرج النص وصُحّح يدوياً)، والإنجليزية ترجمة مقترحة غير رسمية. تُضاف الدفعات تباعاً. */
window.ETEC_HL_DONE = ["1-1-1-1", "1-1-1-2", "1-2-1-1", "1-2-1-2", "1-2-1-3", "1-2-1-4", "1-2-1-5", "1-3-1-1", "1-3-1-2", "1-3-1-3", "1-4-1-1", "1-4-1-2", "1-4-1-3", "1-4-1-4", "1-4-1-5", "1-4-1-6", "1-4-1-7", "1-5-1-1", "1-5-1-2", "2-1-1-1", "2-1-1-2", "2-1-1-3", "2-1-1-4", "2-1-1-5", "2-1-1-6", "2-1-1-7", "2-1-1-8", "2-1-1-9"];
window.ETEC_HL = {"1-1-1-1": [{"ar": "إعداد خطة تشغيلية شاملة ومكتملة العناصر، بحيث تتضمن: تحليل الواقع، وأهدافاً محددة، وبرامج مزمنة، وأنشطة ومبادرات نوعية، وإجراءات تنفيذ واضحة، مع تحديد الأدوار والمسؤوليات، ومؤشرات أداء لقياس تحقق الأهداف.", "en": "Prepare a comprehensive, fully elaborated operational plan that includes: situation analysis, specific goals, time-bound programs, qualitative activities and initiatives, clear implementation procedures, defined roles and responsibilities, and performance indicators to measure goal achievement."}, {"ar": "مشاركة أكثر من 90% من منسوبي المدرسة في إعداد الخطة التشغيلية.", "en": "More than 90% of school staff take part in preparing the operational plan."}, {"ar": "صياغة الأهداف التفصيلية في الخطة التشغيلية؛ بحيث تكون أهدافاً تطويرية وطموحة، تراعي الإبداع والابتكار، وتكون محددة وواضحة وشاملة وقابلة للتطبيق والقياس، وفق مستويات الأهداف (قريبة المدى/متوسطة المدى/بعيدة المدى).", "en": "Formulate the detailed goals of the operational plan so that they are developmental and ambitious, take creativity and innovation into account, and are specific, clear, comprehensive, applicable and measurable, according to goal levels (short-, medium- and long-term)."}, {"ar": "يتضمن كل هدف: مؤشراً لقياسه، وخطاً أساسياً، ومستهدفاً زمنياً، ومسؤولاً عن التنفيذ، وآلية دورية لقياس التقدم، مع تحديد مستوى الهدف (قريب/متوسط/بعيد) ضمن بطاقة الهدف.", "en": "Each goal includes: an indicator to measure it, a baseline, a time-bound target, a person responsible for implementation, and a periodic mechanism for measuring progress, with the goal level (short/medium/long) stated on the goal card."}, {"ar": "تصميم البرامج والأنشطة في الخطة التشغيلية؛ بحيث تكون مرتبطة بالأهداف التطويرية، ومزمنة، وتغطي جميع المجالات.", "en": "Design the programs and activities in the operational plan so that they are linked to the developmental goals, time-bound, and cover all domains."}, {"ar": "تضمين كل برنامج الهدف التطويري المرتبط به، ومؤشره، وخطوات تنفيذ واضحة.", "en": "Include in each program its related developmental goal, its indicator, and clear implementation steps."}, {"ar": "تحديد الموارد، والجدول الزمني، والفئات المستهدفة، إضافةً إلى مواءمة شاملة لجميع المتعلمين؛ بمن فيهم ذوو الإعاقة، والمتفوقون، والموهوبون؛ لكل برنامج أو نشاط.", "en": "Specify the resources, timeline and target groups, in addition to comprehensive accommodation for all learners, including learners with disabilities, high achievers and gifted learners, for every program or activity."}, {"ar": "تحديد الأدوار وتوزيع المسؤوليات؛ لتنفيذ الخطة التشغيلية على منسوبي المدرسة؛ بحيث تكون متسقة مع الأدوار المعتمدة لمنسوبي المدرسة، وتكون الأدوار مزمنة ومحددة وموزعة على البرامج والأنشطة، وشاملة للمهام والمسؤوليات.", "en": "Define roles and distribute responsibilities for implementing the operational plan among school staff, so that they are consistent with the approved roles of school staff, and the roles are time-bound, specific, distributed across programs and activities, and cover all tasks and responsibilities."}], "1-1-1-2": [{"ar": "إعداد خطة متابعة زمنية للبرامج والأنشطة وتنفيذها.", "en": "Prepare and implement a time-based follow-up plan for the programs and activities."}, {"ar": "تحديد إجراءات متابعة واضحة، وتحديد الأدوار والمسؤوليات.", "en": "Define clear follow-up procedures, roles and responsibilities."}, {"ar": "رصد المشكلات والتحديات أثناء التنفيذ، وتحليل مسبباتها وتصنيفها بحسب الأولوية ودرجة التأثير؛ تمهيداً لمعالجتها.", "en": "Monitor problems and challenges during implementation, analyze their causes and classify them by priority and degree of impact, in preparation for addressing them."}, {"ar": "تقديم الحلول والبدائل لتطوير البرامج والأنشطة، مع تحديد مؤشرات لقياس تقدم التنفيذ.", "en": "Offer solutions and alternatives to develop the programs and activities, and set indicators to measure implementation progress."}, {"ar": "تنفيذ تقويم شامل للخطة والبرامج، مع توفير أدوات متنوعة للتقويم وجمع الأدلة.", "en": "Carry out a comprehensive evaluation of the plan and programs, providing varied evaluation tools and evidence collection."}, {"ar": "مراجعة الخطة وأهدافها، وبرامجها وأنشطتها، ومراجعة المؤشرات لقياس تقدم التنفيذ، ومراجعة الموارد البشرية والمادية والمالية؛ لتحديد نقاط القوة وفرص التحسين، وتقديم الحلول والبدائل لتطوير الأداء.", "en": "Review the plan, its goals, programs and activities, the indicators used to measure implementation progress, and the human, material and financial resources, in order to identify strengths and improvement opportunities and offer solutions and alternatives to develop performance."}, {"ar": "إشراك المجتمع المدرسي في مراجعة الخطة وتطويرها، وتحديد المشكلات والتحديات المتوقعة، واقتراح الحلول والبدائل.", "en": "Involve the school community in reviewing and developing the plan, identifying expected problems and challenges, and proposing solutions and alternatives."}, {"ar": "تطوير الخطة المدرسية استناداً إلى نتائج التقويم؛ عبر تحليل النتائج وتحديد جوانب التطوير، ثم صياغة أهداف تطوير واضحة، وتحديد البرامج والأنشطة المناسبة لها، ووضع إجراءات تطويرية واضحة.", "en": "Develop the school plan based on evaluation results, by analyzing results and identifying areas for development, then formulating clear development goals, identifying suitable programs and activities for them, and setting clear developmental procedures."}], "1-2-1-1": [{"ar": "تنفيذ برامج توعوية للمجتمع المدرسي والمحلي؛ لتعزيز القيم الإسلامية والهوية الوطنية والولاء للقيادة الرشيدة.", "en": "Implement awareness programs for the school and local community to strengthen Islamic values, national identity and loyalty to the wise leadership."}, {"ar": "تضمين القيم الإسلامية والهوية الوطنية والولاء للقيادة الرشيدة في خطة المدرسة وبرامجها وأنشطتها.", "en": "Embed Islamic values, national identity and loyalty to the wise leadership in the school's plan, programs and activities."}, {"ar": "دمج القيم الإسلامية والهوية الوطنية والولاء للقيادة الرشيدة في جميع الممارسات والأنشطة الصفية اليومية.", "en": "Integrate Islamic values, national identity and loyalty to the wise leadership into all daily classroom practices and activities."}, {"ar": "تنفيذ برامج صفية وغير صفية؛ لتعزيز القيم الإسلامية والهوية الوطنية والولاء للقيادة الرشيدة لدى المتعلمين.", "en": "Implement classroom and non-classroom programs to strengthen Islamic values, national identity and loyalty to the wise leadership among learners."}, {"ar": "ترسيخ القيم الإسلامية؛ من خلال ميثاق سلوك يومي (التحية، والأمانة، والمحافظة على الممتلكات)، وإبراز الهوية الوطنية بصرياً (العلم، والشعار، وعبارات قيمية، وصور وقدوات وطنية) في البيئة المدرسية.", "en": "Entrench Islamic values through a daily code of conduct (greeting, honesty, and caring for property), and highlight national identity visually (the flag, the emblem, value-based phrases, and national images and role models) in the school environment."}, {"ar": "الاحتفاء بالمناسبات الوطنية (اليوم الوطني، ويوم التأسيس، ويوم العلم) بشكل منظم يشارك فيه جميع الطلبة.", "en": "Celebrate national occasions (National Day, Founding Day and Flag Day) in an organized way in which all students take part."}, {"ar": "توزيع الأدوار والمسؤوليات على منسوبي المدرسة؛ لضمان جودة التطبيق، مع المتابعة وتقديم التغذية الراجعة.", "en": "Distribute roles and responsibilities among school staff to ensure quality of implementation, with follow-up and feedback."}, {"ar": "تفعيل الشراكة مع أولياء الأمور والمجتمع المحلي؛ لدعم القيم الإسلامية والهوية الوطنية.", "en": "Activate partnership with parents and the local community to support Islamic values and national identity."}], "1-2-1-2": [{"ar": "تنفيذ إجراءات واضحة لنشر قواعد السلوك الوظيفي، وقيم مهنة التعليم وأخلاقياتها، في المجتمع المدرسي.", "en": "Implement clear procedures to disseminate the professional code of conduct and the values and ethics of the teaching profession in the school community."}, {"ar": "تنفيذ برامج توعوية شاملة عن قيمة مهنة التعليم وأخلاقياتها بشكل مستمر.", "en": "Continuously implement comprehensive awareness programs about the value and ethics of the teaching profession."}, {"ar": "تنفيذ برامج وأنشطة متنوعة تعزز العلاقات الإيجابية القائمة على الاحترام المتبادل، والتعاون، والثقة بين منسوبي المدرسة.", "en": "Implement varied programs and activities that foster positive relationships based on mutual respect, cooperation and trust among school staff."}, {"ar": "متابعة التزام منسوبي المدرسة بقيم مهنة التعليم وأخلاقياتها بشكل مستمر.", "en": "Continuously monitor school staff's adherence to the values and ethics of the teaching profession."}, {"ar": "تقديم حوافز متنوعة لتشجيع منسوبي المدرسة على تطبيق قواعد السلوك الوظيفي، وأخلاقيات مهنة التعليم داخل المجتمع المدرسي وخارجه.", "en": "Provide varied incentives to encourage school staff to apply the professional code of conduct and the ethics of the teaching profession inside and outside the school community."}, {"ar": "تنفيذ إجراءات رسمية للمساءلة بشأن مخالفات قيم مهنة التعليم وأخلاقياتها.", "en": "Implement formal accountability procedures for violations of the values and ethics of the teaching profession."}, {"ar": "تنفيذ إجراءات عملية لضمان التزام جميع منسوبي المدرسة بقواعد السلوك الوظيفي، وقيم مهنة التعليم.", "en": "Implement practical procedures to ensure that all school staff comply with the professional code of conduct and the values of the teaching profession."}, {"ar": "توثيق نتائج متابعة الالتزام بقيم مهنة التعليم وأخلاقياتها بصورة دورية، وتحليلها؛ لتحديد جوانب التحسين واتخاذ الإجراءات اللازمة لتعزيز الالتزام.", "en": "Periodically document and analyze the results of monitoring adherence to the values and ethics of the teaching profession, to identify improvement areas and take the necessary actions to strengthen compliance."}], "1-2-1-3": [{"ar": "اعتماد حزمة إجراءات الانضباط المدرسي في المدرسة (وقائية/علاجية/تصحيحية) وفق قواعد السلوك والمواظبة، وتعميمها على جميع منسوبي المجتمع المدرسي والأسرة.", "en": "Adopt a package of school discipline procedures (preventive/remedial/corrective) in line with the behavior and attendance rules, and circulate it to all members of the school community and to families."}, {"ar": "إعداد إجراءات واضحة ومتنوعة وتنفيذها؛ لنشر قواعد السلوك والمواظبة في المجتمع المدرسي والمجتمع المحلي.", "en": "Prepare and implement clear and varied procedures to disseminate the behavior and attendance rules in the school and local communities."}, {"ar": "إعداد وتنفيذ خطة وقائية داعمة للانضباط المدرسي تتضمن التوعية والتدخل المبكر ورصد مؤشرات الخطورة داخل البيئة المدرسية.", "en": "Prepare and implement a preventive plan supporting school discipline that includes awareness, early intervention and monitoring of risk indicators within the school environment."}, {"ar": "تنفيذ برامج توعوية دورية لترسيخ قواعد السلوك والانضباط داخل المجتمع المدرسي.", "en": "Implement periodic awareness programs to entrench the rules of behavior and discipline within the school community."}, {"ar": "تطبيق إجراءات تعزيز السلوك الإيجابي داخل المدرسة وربطها بحوافز تربوية داعمة للانضباط.", "en": "Apply procedures to reinforce positive behavior within the school and link them to educational incentives that support discipline."}, {"ar": "تطبيق إجراءات ضبط المخالفات السلوكية وفق التدرج المناسب، وتحديد الإجراء المتخذ بناءً على طبيعة المخالفة وتكرارها ضمن إطار القواعد المعتمدة.", "en": "Apply procedures to address behavioral violations with appropriate progression, determining the action taken based on the nature and recurrence of the violation within the approved rules."}, {"ar": "متابعة شواهد الالتزام (حصر الغيابات، والمخالفات السلوكية، وحالات الانضباط)، ودراسة أسباب الغياب وتحليلها، وإعداد خطط لمعالجة الغياب بالشراكة مع الأسرة.", "en": "Monitor evidence of compliance (counting absences, behavioral violations and discipline cases), study and analyze the causes of absence, and prepare plans to address absence in partnership with families."}, {"ar": "توثيق إجراءات الانضباط والمخالفات والسجلات المرتبطة بها في الأنظمة التقنية المعتمدة وفق آلية رسمية، وإعداد تقرير مفصل بالإجراءات والخدمات المقدمة لمعالجة حالات الانضباط ورفعه للجهات ذات العلاقة وفق التسلسل التنظيمي، مع مراجعة دورية لنتائج الالتزام وإصدار ما يلزم من إجراءات تعزيز/تصحيح لضمان الاستمرارية والالتزام.", "en": "Document discipline procedures, violations and related records in the approved technical systems through a formal mechanism, prepare a detailed report on the procedures and services provided to address discipline cases and submit it to the relevant bodies following the organizational chain, with periodic review of compliance results and issuing the necessary reinforcement/corrective actions to ensure continuity and compliance."}], "1-2-1-4": [{"ar": "إعداد إجراءات محددة وتنفيذها؛ للكشف المبكر عن المشكلات السلوكية لدى المتعلمين؛ بمن فيهم ذوو الإعاقة والموهوبون.", "en": "Prepare and implement specific procedures for the early detection of behavioral problems among learners, including learners with disabilities and gifted learners."}, {"ar": "إعداد خطة مدرسية وتنفيذها؛ لتعزيز السلوك الإيجابي لدى المتعلمين؛ بمن فيهم ذوو الإعاقة والموهوبون، وفق احتياجاتهم.", "en": "Prepare and implement a school plan to strengthen positive behavior among learners, including learners with disabilities and gifted learners, according to their needs."}, {"ar": "تطبيق برامج وأنشطة توعوية ووقائية وعلاجية؛ لتعزيز السلوك الإيجابي والحد من السلوكيات السلبية.", "en": "Apply awareness, preventive and remedial programs and activities to strengthen positive behavior and reduce negative behaviors."}, {"ar": "تصميم البرامج والأنشطة التربوية الداعمة للسلوك الإيجابي؛ بحيث تكون مرتبطة بنتائج تشخيص المشكلات السلوكية.", "en": "Design educational programs and activities that support positive behavior, linked to the results of diagnosing behavioral problems."}, {"ar": "متابعة نتائج تطبيق البرامج والأنشطة، وقياس أثرها بشكل دوري.", "en": "Follow up the results of implementing the programs and activities and measure their impact periodically."}, {"ar": "مراعاة شمول البرامج والأنشطة لجميع المتعلمين؛ بمن فيهم ذوو الإعاقة والموهوبون، وفق احتياجاتهم.", "en": "Ensure that the programs and activities include all learners, including learners with disabilities and gifted learners, according to their needs."}, {"ar": "تقديم حوافز متنوعة لتعزيز السلوك الإيجابي لدى المتعلمين.", "en": "Provide varied incentives to strengthen positive behavior among learners."}, {"ar": "التواصل بشكل مستمر مع الأسرة؛ لمناقشة المشكلات السلوكية وتقديم الحلول لمعالجتها.", "en": "Communicate continuously with the family to discuss behavioral problems and offer solutions to address them."}], "1-2-1-5": [{"ar": "إعداد خطة متكاملة للأنشطة الإثرائية الصفية وغير الصفية وتنفيذها، وفق الأنظمة والتعليمات.", "en": "Prepare and implement an integrated plan for classroom and non-classroom enrichment activities, in accordance with regulations and instructions."}, {"ar": "تنفيذ أنشطة إثرائية غير صفية متنوعة شاملة لجميع المتعلمين، ومنهم ذوو الإعاقة والموهوبون، مع تقديم حوافز تشجيعية عينية أو معنوية، تشجعهم على المشاركة في الأنشطة، مع متابعة تنفيذ الأنشطة والبرامج بشكل مستمر.", "en": "Implement varied non-classroom enrichment activities that include all learners, including learners with disabilities and gifted learners, with tangible or moral incentives that encourage them to participate, while continuously monitoring the implementation of activities and programs."}, {"ar": "تطبيق أساليب للكشف عن مواهب وقدرات المتعلمين، وربط البرامج والأنشطة بنتائج تشخيص مواهبهم وقدراتهم.", "en": "Apply methods to identify learners' talents and abilities, and link programs and activities to the results of diagnosing their talents and abilities."}, {"ar": "تنفيذ برامج وأنشطة متنوعة؛ لتطوير مواهب المتعلمين وقدراتهم.", "en": "Implement varied programs and activities to develop learners' talents and abilities."}, {"ar": "تطبيق أساليب متنوعة؛ لتحفيز المتعلمين على المشاركة في مقياس موهبة، وتدعم مواهب المتعلمين، وتشجعهم على التميز.", "en": "Apply varied methods to motivate learners to take part in the Mawhiba scale, support learners' talents, and encourage them to excel."}, {"ar": "نشر الوعي والثقافة في المجتمع المدرسي والمجتمع المحلي، عن المسابقات الوطنية والدولية، وطرق المشاركة فيها.", "en": "Spread awareness and culture in the school and local communities about national and international competitions and ways to participate in them."}, {"ar": "تقديم حوافز متنوعة تشجع المتعلمين على المشاركة في المسابقات الوطنية والدولية، وتقديم الدعم الكامل للمشاركين في المسابقات الوطنية والدولية، مع أهمية الاحتفاء بمنجزات المتعلمين ومنسوبي المدرسة في المسابقات الوطنية والدولية.", "en": "Provide varied incentives that encourage learners to take part in national and international competitions, give full support to participants, and celebrate the achievements of learners and school staff in them."}, {"ar": "تنفيذ برامج إثرائية وأنشطة متنوعة، شاملة لجميع المتعلمين في المرحلة الثانوية بمن فيهم ذوو الإعاقة، وذلك لتهيئة المتعلمين في هذه المرحلة لمستقبلهم الأكاديمي، مع تقديم حوافز تشجع المتعلمين على المشاركة في هذه الأنشطة والبرامج، وتفعيل شراكات مع مؤسسات المجتمع ذات العلاقة في هذا الجانب.", "en": "Implement enrichment programs and varied activities for all learners in the secondary stage, including learners with disabilities, to prepare them for their academic future, with incentives encouraging participation in these activities and programs, and by activating partnerships with relevant community institutions in this area."}], "1-3-1-1": [{"ar": "إعداد خطة متكاملة لتعزيز العمل التعاوني بين منسوبي المدرسة، وتنفيذها، ومراجعتها دورياً.", "en": "Prepare an integrated plan to strengthen collaborative work among school staff, implement it, and review it periodically."}, {"ar": "تضمين أنشطة ومهام في الخطة تشجع التعاون والعمل بروح الفريق.", "en": "Include in the plan activities and tasks that encourage cooperation and teamwork."}, {"ar": "شمول جميع منسوبي المدرسة في تنفيذ الأنشطة والمهام التعاونية.", "en": "Involve all school staff in carrying out the collaborative activities and tasks."}, {"ar": "تعزيز العمل الجماعي بأساليب وطرائق مبتكرة داخل المدرسة.", "en": "Strengthen teamwork within the school through innovative methods and approaches."}, {"ar": "متابعة أثر تطبيق برامج التعاون والعمل الجماعي من خلال أدوات قياس الرضا.", "en": "Follow up the impact of the cooperation and teamwork programs through satisfaction measurement tools."}], "1-3-1-2": [{"ar": "تنفيذ أنشطة وبرامج متنوعة للتوعية بدور الأسرة في تعلم أبنائها والتحضير لمستقبلهم.", "en": "Implement varied activities and programs to raise awareness of the family's role in their children's learning and in preparing for their future."}, {"ar": "الاستمرار في تنفيذ الأنشطة والبرامج بشكل منتظم، على أن تشمل المجتمع المدرسي وأولياء الأمور والأسر.", "en": "Continue implementing the activities and programs regularly, covering the school community, parents and families."}, {"ar": "مشاركة الأسرة في تقويم تعلم أبنائها، ومتابعة أداء المهام والواجبات.", "en": "Engage the family in evaluating their children's learning and in following up on tasks and assignments."}, {"ar": "مشاركة الأسرة في تحديد المشكلات التي تواجه تعلم أبنائها، وتقديم الحلول المناسبة.", "en": "Engage the family in identifying the problems facing their children's learning and in proposing suitable solutions."}, {"ar": "تقديم حوافز تدعم مشاركة الأسرة في الأنشطة والبرامج لدعم تعلم أبنائها.", "en": "Provide incentives that support family participation in activities and programs that support their children's learning."}, {"ar": "تفعيل أساليب وطرق متنوعة للتواصل مع الأسرة بشكل مستمر، وتزويدها بمعلومات وبيانات عن تعلم أبنائها وكيفية دعمهم.", "en": "Activate varied methods of continuous communication with the family, providing information and data on their children's learning and how to support them."}, {"ar": "إتاحة الفرصة لمشاركة الأسرة في الأنشطة والفعاليات التي تنفذها المدرسة (استثمار خبرات الوالدين التخصصية).", "en": "Provide opportunities for families to take part in the school's activities and events (drawing on parents' specialist expertise)."}, {"ar": "مشاركة الأسرة في تقويم خدمات المدرسة التعليمية وتطويرها.", "en": "Engage the family in evaluating and developing the school's educational services."}], "1-3-1-3": [{"ar": "تفعيل أساليب وطرق متنوعة للتواصل والتعاون مع مؤسسات المجتمع لدعم تعلم المتعلمين وتلبية احتياجات ذوي الإعاقة والموهوبين، وذلك بشكل مستمر.", "en": "Activate varied methods of communication and cooperation with community institutions, on an ongoing basis, to support learners' learning and meet the needs of learners with disabilities and gifted learners."}, {"ar": "تنفيذ برامج وأنشطة لتوعية المجتمع المدرسي والمجتمع المحلي بأهمية مشاركة مؤسسات المجتمع في تعزيز عملية التعلم.", "en": "Implement programs and activities that raise awareness in the school and local communities of the importance of community institutions' participation in strengthening learning."}, {"ar": "عقد شراكات مجتمعية مع المؤسسات الوطنية (مثل: المؤسسات والمراكز ذات العلاقة بالموهبة والإبداع وذوي الإعاقة).", "en": "Establish community partnerships with national institutions (e.g. institutions and centers related to talent, creativity and disability)."}, {"ar": "دعم تبادل الخبرات ونقل المعرفة مع المدارس الأخرى لتعزيز التعلم (زيارات مدرسية، واجتماعات عمل، وتطوير مهني مشترك، إلخ).", "en": "Support the exchange of expertise and knowledge transfer with other schools to strengthen learning (school visits, working meetings, joint professional development, etc.)."}, {"ar": "تنفيذ أنشطة وبرامج لتعريف المجتمع المدرسي بالخدمات التي تقدمها المؤسسات ذات العلاقة بالموهوبين وذوي الإعاقة.", "en": "Implement activities and programs that familiarize the school community with the services offered by institutions concerned with gifted learners and learners with disabilities."}, {"ar": "الاستفادة من الخدمات التي تقدمها المؤسسات ذات العلاقة بالموهوبين وذوي الإعاقة بأساليب وطرق متنوعة، وتوثيق جميع الشراكات.", "en": "Make use of the services offered by these institutions through varied methods, and document all partnerships."}, {"ar": "تقديم الدعم والمساندة للمؤسسات الوطنية التي تعنى بتلبية احتياجات ذوي الإعاقة والموهوبين.", "en": "Provide support and assistance to national institutions that work to meet the needs of learners with disabilities and gifted learners."}, {"ar": "تقديم خدمات متنوعة (الأندية الرياضية، والبرامج التدريبية، والمكتبة، والمسرح، ...) للمجتمع المحلي.", "en": "Offer varied services (sports clubs, training programs, the library, the theater, etc.) to the local community."}], "1-4-1-1": [{"ar": "تنفيذ آليات وإجراءات واضحة ومعلنة لاستقطاب الكوادر التعليمية المؤهلة.", "en": "Implement clear, publicly announced mechanisms and procedures for attracting qualified teaching staff."}, {"ar": "التعاقد مع كادر تعليمي مكتمل (عدد المعلمين يغطي جميع المجالات التخصصية).", "en": "Contract a complete teaching staff (the number of teachers covers all specialization areas)."}, {"ar": "التعاقد مع كادر تعليمي مؤهل (90% فأكثر من الكادر التعليمي بكالوريوس فأعلى).", "en": "Contract a qualified teaching staff (90% or more of teaching staff hold a bachelor's degree or higher)."}, {"ar": "رفع توافق مؤهل وخبرة الكادر التعليمي مع المجال التخصصي الذي يدرّسه إلى (90% فأكثر) من الكادر التعليمي.", "en": "Raise the match between teaching staff's qualifications and experience and the subject they teach to 90% or more of the teaching staff."}], "1-4-1-2": [{"ar": "تنفيذ آليات واضحة وإجراءات معلنة لاستقطاب الكوادر الإدارية المؤهلة.", "en": "Implement clear mechanisms and announced procedures for attracting qualified administrative staff."}, {"ar": "التعاقد مع كادر إداري مكتمل وفقاً لحجم المدرسة.", "en": "Contract a complete administrative staff according to the size of the school."}, {"ar": "التعاقد مع كادر إداري مؤهل (90% فأكثر من الكادر الإداري دبلوم مشارك فأعلى).", "en": "Contract a qualified administrative staff (90% or more of administrative staff hold an associate diploma or higher)."}, {"ar": "رفع توافق مؤهل وخبرة الكادر الإداري مع العمل المكلف به إلى (90% فأكثر) من الكادر الإداري.", "en": "Raise the match between administrative staff's qualifications and experience and their assigned work to 90% or more of the administrative staff."}, {"ar": "تعزيز التحفيز والتقدير للكادر الإداري المتميز لضمان استدامة الأداء الفاعل.", "en": "Strengthen motivation and recognition for outstanding administrative staff to ensure sustained effective performance."}, {"ar": "تطبيق نظام متابعة وتقويم دوري لقياس فاعلية الكادر الإداري ومدى توافقه مع متطلبات العمل المكلف به.", "en": "Apply a periodic monitoring and evaluation system to measure administrative staff's effectiveness and their fit with the requirements of their assigned work."}], "1-4-1-3": [{"ar": "إعداد وتنفيذ خطة مالية سنوية وتقرير مالي معتمد، يتضمن توثيق جميع المعاملات (دخل وصرف)، ويُراجَع ويُحدَّث بشكل دوري بمشاركة أصحاب العلاقة؛ لضمان الاستدامة المالية.", "en": "Prepare and implement an annual financial plan and an approved financial report that documents all transactions (income and expenditure), and is reviewed and updated periodically with stakeholder participation to ensure financial sustainability."}, {"ar": "توزيع الموارد المالية وفق الخطة التشغيلية، وبما يتناسب مع أولويات المدرسة؛ لزيادة الفاعلية التعليمية وتحقيق أهدافها.", "en": "Distribute financial resources according to the operational plan and in line with the school's priorities, to increase educational effectiveness and achieve its goals."}, {"ar": "تخصيص بند من الميزانية لعمليات التطوير المهني وبرامجه.", "en": "Allocate a budget item for professional development processes and programs."}, {"ar": "تطبيق إجراءات واضحة وضوابط للمراجعة والتدقيق، مع توثيق الموارد المالية وعمليات الدخل والصرف، وإعداد تقارير مالية دورية، إضافة إلى اعتماد آليات وضوابط دقيقة لعمليات الصرف، وآليات واضحة للمساءلة.", "en": "Apply clear procedures and controls for review and audit, documenting financial resources and income and expenditure operations, preparing periodic financial reports, and adopting precise mechanisms and controls for spending as well as clear accountability mechanisms."}, {"ar": "الالتزام بتغطية جميع مصروفات المدرسة التشغيلية من مواردها المالية، بما يحقق التوافق بين الإيرادات والمصروفات وفق الخطة التشغيلية، مع تطبيق إجراءات واضحة للمراجعة والتدقيق بشكل مستمر، وضوابط لمتابعة الالتزامات المالية، وإعداد التقارير المالية الدورية التي تُظهر التنوع في الموارد والنمو في الإيرادات، مع توافر احتياطي مالي لتغطية المصروفات الطارئة.", "en": "Commit to covering all of the school's operating expenses from its own financial resources, achieving alignment between revenues and expenses per the operational plan, with continuous clear review and audit procedures, controls for monitoring financial obligations, and periodic financial reports showing diversity of resources and growth in revenue, together with a financial reserve to cover emergency expenses."}, {"ar": "الالتزام بوضع سياسات وضوابط واضحة للرسوم وإجراءات التحصيل بمشاركة أصحاب المصلحة في صياغتها واعتمادها، ونشرها بوسائل وأساليب متعددة، وإبلاغ أولياء الأمور بالرسوم وإجراءات الدفع بطرق متنوعة وموثقة، وتوفير برامج توعوية لشرح سياسات التحصيل، والإعلان عن التغييرات في الرسوم قبل بداية العام الدراسي بمدة كافية، مع متابعة عمليات دفع الرسوم بشكل مستمر وموثق.", "en": "Commit to establishing clear fee policies and collection procedures, with stakeholders participating in drafting and approving them; publish them through multiple means; notify parents of fees and payment procedures through varied, documented channels; provide awareness programs explaining collection policies; announce fee changes sufficiently ahead of the academic year; and monitor fee payments continuously and with documentation."}], "1-4-1-4": [{"ar": "إعداد خطة تستهدف تقديم الدعم المستمر للمعلمين وتنفيذها؛ لتحقيق نسبة 90% من المعلمين الحاصلين على الرخصة المهنية، مع أهمية حصول بعض المعلمين على رخصة متقدم وخبير.", "en": "Prepare and implement a plan for continuous support to teachers so that 90% of teachers hold the professional license, with some teachers also obtaining the advanced and expert licenses."}, {"ar": "تنفيذ أنشطة وبرامج متنوعة (توعوية وإرشادية) وشاملة لجميع التخصصات حول أهمية الرخصة المهنية.", "en": "Implement varied awareness and guidance activities and programs, covering all specializations, on the importance of the professional license."}, {"ar": "تقديم حوافز لتشجيع المعلمين على الحصول على الرخصة المهنية.", "en": "Provide incentives to encourage teachers to obtain the professional license."}, {"ar": "توفير الدعم الفني والإرشادي للمعلمين أثناء مراحل التقديم والاختبار (ورش تعريفية، ومجموعات تعلم مهنية).", "en": "Provide technical and advisory support to teachers during the application and testing stages (orientation workshops and professional learning groups)."}, {"ar": "تحليل نتائج اختبارات الرخصة المهنية بشكل دوري لتحديد الاحتياجات التدريبية ووضع خطط التحسين المناسبة.", "en": "Periodically analyze professional license test results to identify training needs and set suitable improvement plans."}], "1-4-1-5": [{"ar": "إعداد خطة تطوير مهني تشمل جميع منسوبي المدرسة، وترتبط بنتائج تقويم الأداء الوظيفي، وتلبي احتياجات منسوبي المدرسة، مع أهمية مشاركتهم في تحديد الاحتياجات.", "en": "Prepare a professional development plan covering all school staff, linked to performance appraisal results and meeting staff needs, with staff taking part in identifying those needs."}, {"ar": "نشر الوعي بأهمية التطوير المهني في تطوير الممارسات، وأنواعه، وكيفية المشاركة فيه.", "en": "Raise awareness of the importance of professional development in improving practice, its types, and how to take part."}, {"ar": "تنفيذ برامج وأنشطة متنوعة للتطوير المهني بصورة مستمرة، مع أهمية متابعة التنفيذ.", "en": "Continuously implement varied professional development programs and activities, with follow-up of implementation."}, {"ar": "استخدام أساليب متنوعة وطرائق مستمرة لدعم منسوبي المدرسة على المشاركة في برامج التطوير المهني والالتحاق بالبرامج التدريبية.", "en": "Use varied, ongoing methods to support school staff in taking part in professional development programs and enrolling in training programs."}, {"ar": "تشجيع منسوبي المدرسة على المشاركة في المؤتمرات العلمية والملتقيات والندوات، وفي إجراء الدراسات والبحوث الإجرائية.", "en": "Encourage school staff to take part in scientific conferences, forums and seminars, and to conduct studies and action research."}, {"ar": "الاستفادة من التقنية الرقمية في التطوير المهني المستمر.", "en": "Make use of digital technology in continuous professional development."}, {"ar": "بناء مجتمعات التعلم المهني في المدرسة، وتشجيع منسوبي المدرسة على مشاركة خبراتهم وأفكارهم وتجاربهم التعليمية وتبادلها فيما بينهم، مع أهمية تقديم حوافز لتعزيز المشاركة في مجتمعات التعلم المهنية.", "en": "Build professional learning communities in the school, encouraging staff to share and exchange their experiences, ideas and teaching practices, with incentives to strengthen participation in these communities."}, {"ar": "تطبيق أساليب متنوعة لقياس أثر التدريب بانتظام.", "en": "Apply varied methods to measure the impact of training regularly."}], "1-4-1-6": [{"ar": "نشر ثقافة التقويم الذاتي في المجتمع المدرسي والمجتمع المحلي بطرق وأساليب متنوعة.", "en": "Spread a culture of self-evaluation in the school and local communities through varied methods."}, {"ar": "إعداد خطة إجرائية لتطبيق التقويم الذاتي وتنفيذها.", "en": "Prepare and implement an operational plan for applying self-evaluation."}, {"ar": "تشكيل فريق التقويم الذاتي وفق المعايير المحددة في دليل التقويم الذاتي.", "en": "Form the self-evaluation team according to the criteria set out in the self-evaluation guide."}, {"ar": "عقد اجتماعات ولقاءات وتنفيذ ورش عمل لتهيئة المجتمع المدرسي للتقويم الذاتي.", "en": "Hold meetings and sessions and run workshops to prepare the school community for self-evaluation."}, {"ar": "تطبيق جميع إجراءات التقويم الذاتي بشكل منظم، مع أهمية التقيد بمعايير ومؤشرات التقويم والاعتماد المدرسي في عمليات التقويم.", "en": "Apply all self-evaluation procedures in an organized manner, adhering to the school evaluation and accreditation standards and indicators."}, {"ar": "توثيق جميع إجراءات وعمليات التقويم الذاتي.", "en": "Document all self-evaluation procedures and processes."}, {"ar": "إشراك منسوبي المدرسة وأصحاب المصلحة في التقويم الذاتي.", "en": "Involve school staff and stakeholders in self-evaluation."}, {"ar": "اطلاع منسوبي المدرسة وأصحاب المصلحة على نتائج التقويم الذاتي بانتظام.", "en": "Inform school staff and stakeholders of self-evaluation results regularly."}], "1-4-1-7": [{"ar": "تحليل نتائج التقويم المدرسي، وتحديد نقاط القوة وفرص التحسين، وترتيب المجالات والمؤشرات من حيث أولوية التحسين.", "en": "Analyze school evaluation results, identify strengths and improvement opportunities, and rank domains and indicators by improvement priority."}, {"ar": "إعداد خطة التحسين بحيث تكون مكتملة العناصر، وتتضمن: أهدافاً محددة، وبرامج وأنشطة مزمنة، ومبادرات نوعية، وإجراءات تنفيذ واضحة، مع تحديد الأدوار والمسؤوليات ومؤشرات الإنجاز، مع أهمية مشاركة أكثر من 90% من الكادر التعليمي في إعداد الخطة.", "en": "Prepare a fully elaborated improvement plan that includes specific goals, time-bound programs and activities, qualitative initiatives and clear implementation procedures, with defined roles, responsibilities and achievement indicators, and with more than 90% of teaching staff taking part in preparing it."}, {"ar": "تصميم البرامج والأنشطة والمبادرات في خطة التحسين بحيث تغطي جميع المجالات الأولى بالتحسين، وكل برنامج يتضمن خطوات تنفيذ واضحة، مع تحديد المسؤوليات والموارد والجدول الزمني والفئات المستهدفة.", "en": "Design the programs, activities and initiatives in the improvement plan so that they cover all priority areas for improvement, each program having clear implementation steps, with defined responsibilities, resources, timeline and target groups."}, {"ar": "تنفيذ خطة التحسين مع المتابعة المستمرة.", "en": "Implement the improvement plan with continuous follow-up."}, {"ar": "تقييم خطة التحسين بشكل منتظم، مع رصد المشكلات والتحديات، وتقديم الحلول والبدائل.", "en": "Evaluate the improvement plan regularly, tracking problems and challenges and offering solutions and alternatives."}, {"ar": "تطوير خطة التحسين بشكل مستمر.", "en": "Continuously develop the improvement plan."}], "1-5-1-1": [{"ar": "اعتماد إجراءات حماية حقوق المتعلمين وحمايتهم داخل المدرسة، وتعميمها على منسوبي المدرسة والطلبة وأولياء الأمور، والتأكيد على عدم التسامح مع أي إيذاء أو إساءة أو تمييز.", "en": "Adopt procedures to protect learners' rights and safeguard them within the school, circulate them to staff, students and parents, and stress zero tolerance of any harm, abuse or discrimination."}, {"ar": "تنفيذ برامج توعوية دورية بحقوق المتعلمين وسبل الحماية (العنف/الإهمال/التنمر)، وتوضيح آليات الإبلاغ وطلب المساعدة داخل المدرسة وخارجها.", "en": "Run periodic awareness programs on learners' rights and means of protection (violence/neglect/bullying), clarifying how to report and seek help inside and outside the school."}, {"ar": "تطبيق قواعد السلوك والمواظبة بما يضمن حفظ حقوق المتعلمين داخل البيئة المدرسية، وتعزيز السلوك الإيجابي والحد من السلوكيات التي تمس السلامة أو الكرامة.", "en": "Apply the rules of conduct and attendance in a way that safeguards learners' rights in the school environment, promoting positive behavior and limiting behaviors that affect safety or dignity."}, {"ar": "تفعيل إجراءات الرصد المبكر لمؤشرات الخطر (عنف/تنمر/إهمال/مشكلات سلوكية حادة) وإحالتها وفق النماذج المعتمدة داخل المدرسة.", "en": "Activate early-detection procedures for risk indicators (violence/bullying/neglect/severe behavioral problems) and refer cases using the school's approved forms."}, {"ar": "تنفيذ إجراءات التبليغ الرسمية عند الاشتباه أو التحقق، وفق ما تقرره الأدلة والأنظمة (مثل: تبليغ إدارة التعليم، والجهات الأمنية عند الحاجة، وجهات حماية الطفل/العنف الأسري، والجهات الصحية).", "en": "Carry out official reporting procedures upon suspicion or confirmation, as the guides and regulations require (e.g. reporting to the education department, security authorities when needed, child protection/domestic violence bodies, and health authorities)."}, {"ar": "ضمان توثيق الحالات والإجراءات المتخذة وحفظ السجلات بسرية، وتحديد صلاحيات الاطلاع وفق الضوابط.", "en": "Ensure that cases and the actions taken are documented, records are kept confidential, and access permissions are defined according to the rules."}, {"ar": "تطبيق تكييفات وإجراءات حماية شاملة تراعي جميع المتعلمين (ومنهم ذوو الإعاقة والموهوبون) في البرامج والأنشطة والإشراف والبيئة الآمنة، بما يمنع أي تمييز أو إقصاء.", "en": "Apply inclusive accommodations and protection procedures that take all learners into account (including learners with disabilities and gifted learners) in programs, activities, supervision and a safe environment, preventing any discrimination or exclusion."}, {"ar": "مراجعة دورية لالتزام المدرسة بإجراءات حماية الحقوق والحماية (شهرياً/فصلياً)، وتحليل الملاحظات والحالات، وإصدار تحسينات وإجراءات تصحيحية؛ لضمان الاستمرارية ورفع مستوى الأمان.", "en": "Periodically review the school's compliance with rights-protection and safeguarding procedures (monthly/termly), analyze observations and cases, and issue improvements and corrective actions to ensure continuity and raise the level of safety."}], "1-5-1-2": [{"ar": "تنفيذ برامج وقائية تهدف إلى الحد من المشكلات السلوكية والنفسية داخل المدرسة.", "en": "Implement preventive programs aimed at reducing behavioral and psychological problems within the school."}, {"ar": "تنفيذ برامج صفية وأنشطة لاصفية متنوعة تعزز الجانب التربوي والاجتماعي للمتعلمين.", "en": "Implement varied classroom programs and extracurricular activities that strengthen learners' educational and social development."}, {"ar": "تنظيم ندوات تثقيفية للتوعية بالقيم الإيجابية وطرق التعامل مع الضغوط.", "en": "Organize educational seminars to raise awareness of positive values and ways of coping with stress."}, {"ar": "تشجيع المتعلمين على الحوار والمناقشة، وقبول الرأي الآخر في المواقف الصفية والأنشطة غير الصفية.", "en": "Encourage learners to engage in dialogue and discussion and to accept other opinions in classroom situations and extracurricular activities."}, {"ar": "تعزيز التعاون والعلاقات الإيجابية بين المتعلمين والمعلمين، بما يرسخ الاحترام المتبادل.", "en": "Strengthen cooperation and positive relationships between learners and teachers, reinforcing mutual respect."}, {"ar": "تنفيذ برامج (وقائية وإرشادية وعلاجية) لحالات التنمر والعنف.", "en": "Implement preventive, guidance and remedial programs for cases of bullying and violence."}, {"ar": "توفير الاستشارات والدعم النفسي والاجتماعي للمتعلمين بشكل مستمر.", "en": "Provide counseling and psychological and social support to learners on a continuous basis."}, {"ar": "إبراز نتائج أعمال مجالس الحوار الطلابية وتوظيفها في تحسين المناخ المدرسي.", "en": "Highlight the outcomes of student dialogue councils and use them to improve the school climate."}], "2-1-1-1": [{"ar": "تنويع الأنشطة ومصادر التعلم (بصرية، وسمعية، وحسية) في بيئة التعلم وتنظيمها بحيث: (1) تلبي احتياجات جميع المتعلمين، ومنهم ذوو الإعاقة والموهوبون وسريعو التعلم؛ (2) تناسب خصائص المرحلة العمرية؛ (3) تراعي الفروق الفردية بين الطلاب؛ (4) وتحقق سهولة الوصول والاستخدام.", "en": "Diversify learning activities and resources (visual, auditory and tactile) in the learning environment and organize them so that they: (1) meet the needs of all learners, including learners with disabilities, gifted and fast learners; (2) suit the characteristics of the age stage; (3) take individual differences among students into account; and (4) are easy to access and use."}, {"ar": "إدارة الوقت بفاعلية وكفاءة لدعم عملية التعلم بحيث يتم: (1) توزيع الوقت على أنشطة الدرس ومراحله وتجنب التشتيت؛ (2) مراعاة نوع المادة العلمية ومستوى التعقيد؛ (3) التوافق بين عدد الأنشطة وأسلوب تنفيذها مع الوقت المخصص؛ (4) المرونة في إدارة الوقت وفقاً للموقف التعليمي؛ (5) إتاحة الوقت الكافي لجميع المتعلمين لتنفيذ الأنشطة والمناقشة؛ (6) مراعاة الفروق الفردية بين الطلاب في توزيع الوقت.", "en": "Manage time effectively and efficiently to support learning so that: (1) time is distributed across lesson activities and stages while avoiding distraction; (2) the type of subject matter and its complexity are considered; (3) the number of activities and how they are carried out fit the allotted time; (4) time management is flexible according to the teaching situation; (5) all learners are given enough time to carry out activities and discuss; (6) individual differences among students are considered in distributing time."}, {"ar": "إتاحة فرص متكافئة للمتعلمين في عملية التعلم من خلال: (1) المشاركة في الأنشطة المتنوعة؛ (2) استخدام مصادر التعلم والاستفادة منها؛ (3) المناقشة والحوار في الأنشطة الصفية؛ (4) الاستفادة من أساليب التحفيز والتشجيع والدعم.", "en": "Provide learners with equal opportunities in the learning process through: (1) taking part in varied activities; (2) using and benefiting from learning resources; (3) discussion and dialogue in classroom activities; (4) benefiting from methods of motivation, encouragement and support."}], "2-1-1-2": [{"ar": "تزويد المعلمين بالخطة الدراسية للعام الدراسي، وأخذ التوقيعات بالعلم.", "en": "Provide teachers with the study plan for the academic year and obtain signatures of acknowledgment."}, {"ar": "يُعِدّ كل معلم خطة توزيع المنهج الدراسي في بداية العام الدراسي، بهدف تنظيم تنفيذ المحتوى الزمني للوحدات التعليمية، بما يضمن تحقيق الأهداف المعرفية والمهارية والقيمية.", "en": "Each teacher prepares a curriculum distribution plan at the start of the academic year, to organize the timing of delivering the learning units so as to achieve the knowledge, skill and value objectives."}, {"ar": "توفير أنشطة شاملة ومصادر متنوعة لدعم تعلم جميع موضوعات ومحتوى المنهج، مع التركيز على المعارف الرئيسة والمهارات النوعية والقيم الوطنية.", "en": "Provide comprehensive activities and varied resources to support learning of all curriculum topics and content, focusing on core knowledge, specific skills and national values."}, {"ar": "المتابعة الدائمة لتنفيذ المنهج وفق الخطة الزمنية، وتحقيق نواتج التعلم المستهدفة وفق الخطة الدراسية.", "en": "Continuously follow up curriculum delivery according to the timeline, and the achievement of targeted learning outcomes according to the study plan."}, {"ar": "متابعة عمليات التنفيذ بشكل مستمر، وتحديد المشكلات، وتقديم الحلول والبدائل لتنفيذ المناهج في حال التأخر.", "en": "Continuously monitor implementation, identify problems, and offer solutions and alternatives for delivering the curriculum when there is a delay."}, {"ar": "التدخل العاجل واتخاذ إجراءات مناسبة في حال لم يلتزم المعلم بالخطة.", "en": "Intervene urgently and take appropriate action if a teacher does not adhere to the plan."}, {"ar": "تنفيذ برامج التطوير المهني للمعلمين الخاصة بتنفيذ المنهج.", "en": "Implement professional development programs for teachers related to curriculum delivery."}], "2-1-1-3": [{"ar": "تشخيص احتياجات المتعلمين ومستوياتهم لتحديد الاستراتيجيات التعليمية المناسبة لكل فئة.", "en": "Diagnose learners' needs and levels in order to determine the teaching strategies suited to each group."}, {"ar": "إعداد خطة تدريسية مرنة تتضمن استراتيجيات متنوعة تراعي أنماط التعلم المختلفة.", "en": "Prepare a flexible teaching plan that includes varied strategies taking different learning styles into account."}, {"ar": "تطبيق استراتيجيات تدريس نشطة ومتنوعة متمركزة حول الطالب، تسهم في تفعيل دوره الإيجابي في التعلم وتنمية مهارات التفكير والتعلم الذاتي، وفق خصائص المتعلمين واحتياجاتهم، مع أهمية توظيف التقنية التعليمية والوسائط الرقمية لدعم تعلم الطالب وتعزيز التفاعل داخل الصف.", "en": "Apply active, varied, student-centered teaching strategies that activate the student's positive role in learning and develop thinking and self-learning skills according to learners' characteristics and needs, using educational technology and digital media to support learning and enhance classroom interaction."}, {"ar": "مراعاة الفروق الفردية عند تنفيذ الدرس من خلال تكييف الأنشطة والمهام بما يتناسب مع قدرات المتعلمين ومستوياتهم.", "en": "Take individual differences into account when delivering lessons by adapting activities and tasks to learners' abilities and levels."}, {"ar": "تقديم أنشطة إثرائية وداعمة للمتعلمين المتفوقين وذوي الإعاقة وصعوبات التعلم لضمان فرص تعلم متكافئة للجميع.", "en": "Provide enrichment and support activities for high-achieving learners, learners with disabilities and learning difficulties, to ensure equal learning opportunities for all."}, {"ar": "تفعيل أدوات التقويم التكويني لقياس مدى فاعلية الاستراتيجيات المتنوعة في تحسين نواتج التعلم.", "en": "Activate formative assessment tools to measure how effective the varied strategies are in improving learning outcomes."}, {"ar": "تبادل الخبرات بين المعلمين من خلال الزيارات الصفية والمجتمعات المهنية، لرفع كفاءة تطبيق الاستراتيجيات التعليمية المتنوعة.", "en": "Exchange expertise among teachers through classroom visits and professional communities, to raise the efficiency of applying varied teaching strategies."}, {"ar": "متابعة تنفيذ الاستراتيجيات ميدانياً، وتقديم التغذية الراجعة المستمرة لتحسين الأداء.", "en": "Follow up the implementation of strategies in the field and provide continuous feedback to improve performance."}], "2-1-1-4": [{"ar": "تعزيز الوعي بالأمن الرقمي وأخلاقيات التقنية من خلال أنشطة ومبادرات تنمي الاستخدام المسؤول للتقنية واحترام الملكية الفكرية.", "en": "Raise awareness of digital security and technology ethics through activities and initiatives that develop responsible use of technology and respect for intellectual property."}, {"ar": "توفير بيئة تعلم إلكترونية متكاملة بالتجهيزات التقنية والتطبيقات التعليمية اللازمة لتيسير دمج التعلم الصفي والإلكتروني، بما يلبي احتياجات جميع المتعلمين.", "en": "Provide an integrated e-learning environment with the necessary technical equipment and educational applications to facilitate blending classroom and online learning, meeting the needs of all learners."}, {"ar": "إعداد خطة شاملة ومرنة لدمج التقنية الرقمية في التعليم اليومي، تتضمن خطط الطوارئ وآليات المتابعة والتقويم والتحسين المستمر.", "en": "Prepare a comprehensive, flexible plan for integrating digital technology into daily teaching, including contingency plans and mechanisms for monitoring, evaluation and continuous improvement."}, {"ar": "توظيف أدوات التعلم الرقمي بفاعلية وربطها بالممارسات الصفية لدعم التعلم النشط والمستدام.", "en": "Use digital learning tools effectively and link them to classroom practice to support active and sustainable learning."}, {"ar": "تنفيذ أنشطة تعليمية رقمية متنوعة ومبتكرة تشجع استخدام التقنية في التقصي والبحث وتنمية التفكير الإبداعي وحل المشكلات، مع مراعاة الفروق الفردية.", "en": "Carry out varied, innovative digital learning activities that encourage using technology for inquiry and research and developing creative thinking and problem solving, taking individual differences into account."}, {"ar": "توظيف مصادر تعلم رقمية متعددة (وسائط تفاعلية، وتطبيقات تعليمية، ومنصات بحثية) لتلبية احتياجات المتعلمين المختلفة وتنمية مهاراتهم التقنية الرقمية.", "en": "Use multiple digital learning resources (interactive media, educational applications, research platforms) to meet learners' different needs and develop their digital technical skills."}, {"ar": "تقديم برامج دعم وإثراء رقمية للموهوبين والمتقدمين، مع خطط علاجية رقمية للمتعثرين، بما يضمن تلبية الاحتياجات التعليمية المتباينة.", "en": "Provide digital support and enrichment programs for gifted and advanced learners, with digital remedial plans for struggling learners, to ensure that diverse learning needs are met."}, {"ar": "تقديم الدعم الفني والتقني المستمر لضمان جودة التنفيذ ومعالجة التحديات أولاً بأول، مع متابعة أثر الأنشطة الرقمية وتقييمها بطرق مبتكرة لقياس تطور مهارات البحث والاستخدام الآمن للتقنية لدى المتعلمين والمعلمين، ومتابعة جودة دمج التقنية وتحسينها بانتظام.", "en": "Provide continuous technical support to ensure quality of implementation and address challenges promptly, while following up and evaluating the impact of digital activities in innovative ways to measure the development of research skills and safe technology use among learners and teachers, and regularly monitoring and improving the quality of technology integration."}], "2-1-1-5": [{"ar": "إعداد أنشطة تعلم تطبيقية متنوعة ومبتكرة وتنفيذها، ترتبط بالمواقف الحياتية الواقعية وتسهم في تعزيز مهارات التفكير العملي والإبداعي لدى المتعلمين.", "en": "Prepare and carry out varied, innovative applied learning activities linked to real-life situations that strengthen learners' practical and creative thinking skills."}, {"ar": "دمج التعلم القائم على المشاريع وحل المشكلات والاستقصاء ضمن الخطط الدراسية؛ لتشجيع المتعلمين على البحث والاستنتاج والتجريب للوصول إلى المعرفة من خلال الممارسة العملية.", "en": "Integrate project-based learning, problem solving and inquiry into study plans to encourage learners to research, infer and experiment so as to reach knowledge through hands-on practice."}, {"ar": "تفعيل المواقف التعليمية العملية داخل الصف وخارجه عبر تجارب مخبرية وزيارات ميدانية ومهام مجتمعية تحاكي الواقع.", "en": "Activate practical learning situations inside and outside the classroom through laboratory experiments, field visits and community tasks that simulate reality."}, {"ar": "توظيف التقنية والتطبيقات الرقمية التفاعلية (كالوسائط المتعددة والمحاكاة والمنصات التعليمية) لدعم تنفيذ الأنشطة التطبيقية وتعزيز تعلم الطالب الذاتي.", "en": "Use technology and interactive digital applications (such as multimedia, simulation and educational platforms) to support applied activities and strengthen students' self-learning."}, {"ar": "تهيئة بيئات تعلم محفزة للتجريب والتعاون، تتيح فرص التواصل والتعلم الجماعي وتنمي روح المبادرة لدى المتعلمين.", "en": "Create learning environments that stimulate experimentation and collaboration, offering opportunities for communication and group learning and developing a spirit of initiative in learners."}, {"ar": "متابعة تنفيذ الأنشطة التطبيقية وتقييم أثرها على مهارات التفكير العلمي والإبداع وحل المشكلات من خلال أدوات تقويم متنوعة ومؤشرات أداء واضحة.", "en": "Follow up the implementation of applied activities and evaluate their impact on scientific thinking, creativity and problem-solving skills using varied assessment tools and clear performance indicators."}, {"ar": "تطوير قدرات المعلمين على تصميم أنشطة تعلم واقعية ومبتكرة عبر برامج تدريبية ومجتمعات تعلم مهنية مستمرة.", "en": "Develop teachers' ability to design realistic, innovative learning activities through training programs and ongoing professional learning communities."}], "2-1-1-6": [{"ar": "تنفيذ برامج وأنشطة صفية ولاصفية تستهدف تنمية مهارات القراءة والكتابة والمهارات العددية من خلال ممارسات تطبيقية وواقعية تراعي الفروق الفردية بين المتعلمين.", "en": "Implement classroom and extracurricular programs and activities that develop reading, writing and numeracy skills through applied, realistic practices that take individual differences among learners into account."}, {"ar": "توظيف مصادر تعلم متنوعة وغنية تتيح فرصاً للتعلم الذاتي وتدعم اكتساب المهارات الأساسية في بيئات تعلم جاذبة ومحفزة.", "en": "Use varied, rich learning resources that offer opportunities for self-learning and support acquiring basic skills in attractive, stimulating learning environments."}, {"ar": "تنمية مهارات القراءة والفهم والتعبير الكتابي باستخدام استراتيجيات متنوعة كالاستقصاء والمناقشة وطرح الأسئلة والتعلم القائم على المشروعات.", "en": "Develop reading, comprehension and written expression skills using varied strategies such as inquiry, discussion, questioning and project-based learning."}, {"ar": "تنمية المفاهيم والمهارات العددية الأساسية من خلال أنشطة عملية وتطبيقات حياتية تشجع على التفكير الناقد وحل المشكلات.", "en": "Develop basic numeracy concepts and skills through practical activities and real-life applications that encourage critical thinking and problem solving."}, {"ar": "إعداد خطط علاجية وإثرائية مرنة وتنفيذها، تعالج جوانب الضعف وتعزز جوانب القوة، مع متابعة مستمرة لقياس الأثر والتحسين.", "en": "Prepare and implement flexible remedial and enrichment plans that address weaknesses and reinforce strengths, with continuous follow-up to measure impact and improve."}, {"ar": "تفعيل التقنية والتطبيقات الرقمية التفاعلية في تدريس المهارات اللغوية والعددية بما يسهم في تحسين الأداء والتحصيل.", "en": "Use technology and interactive digital applications in teaching language and numeracy skills to help improve performance and attainment."}, {"ar": "تشجيع المتعلمين على المشاركة في المسابقات الوطنية والدولية لتنمية التنافس الإيجابي وتعزيز مهارات القراءة والكتابة والرياضيات.", "en": "Encourage learners to take part in national and international competitions to foster positive competition and strengthen reading, writing and mathematics skills."}, {"ar": "تطوير قدرات المعلمين ومتابعة تنفيذ الخطط بطرق مبتكرة تضمن استدامة التحسين وجودة نواتج التعلم لدى جميع المتعلمين.", "en": "Develop teachers' capabilities and follow up plan implementation in innovative ways that ensure sustained improvement and quality learning outcomes for all learners."}], "2-1-1-7": [{"ar": "تطبيق استراتيجيات تعلم نشط ومتنوعة ومتمركزة حول الطالب (مثل: التعلم القائم على المشكلات، والمشروعات، والاستقصاء، والعصف الذهني) لتنمية مهارات التفكير والبحث والاستنتاج والتقويم لدى المتعلمين.", "en": "Apply varied, active, student-centered learning strategies (such as problem-based learning, projects, inquiry and brainstorming) to develop learners' thinking, research, inference and evaluation skills."}, {"ar": "تصميم أنشطة صفية ولاصفية محفزة للتفكير الإبداعي والنقدي، ترتبط بالمواقف الحياتية الواقعية وتتيح للمتعلمين فرصاً لتوليد أفكار وحلول مبتكرة.", "en": "Design classroom and extracurricular activities that stimulate creative and critical thinking, linked to real-life situations and giving learners opportunities to generate innovative ideas and solutions."}, {"ar": "دمج مهارات التفكير العليا في جميع المواد الدراسية من خلال أنشطة تحليل النصوص وتفسير النتائج واستخلاص المفاهيم وربطها بالتطبيقات العملية.", "en": "Integrate higher-order thinking skills into all subjects through activities such as analyzing texts, interpreting results, drawing out concepts and linking them to practical applications."}, {"ar": "تنفيذ مهام تعلم مفتوحة النهاية تتطلب من المتعلمين البحث والتقصي والمقارنة والتفسير، وتقديم مخرجات تعكس عمق التفكير والتحليل والابتكار.", "en": "Carry out open-ended learning tasks that require learners to research, investigate, compare and interpret, and to produce outputs that reflect depth of thinking, analysis and innovation."}, {"ar": "توظيف التقنية الرقمية والوسائط التفاعلية لتوسيع فرص التعلم والبحث والابتكار وتنمية مهارات التفكير العليا لدى جميع المتعلمين، بمن فيهم الموهوبون وذوو الإعاقة.", "en": "Use digital technology and interactive media to widen opportunities for learning, research and innovation and to develop higher-order thinking skills in all learners, including gifted learners and learners with disabilities."}, {"ar": "تهيئة بيئة تعلم محفزة للنقاش والحوار البناء، تدعم تبادل وجهات النظر وطرح الأسئلة وتقييم الأدلة للوصول إلى استنتاجات منطقية.", "en": "Create a learning environment that stimulates discussion and constructive dialogue, supporting the exchange of viewpoints, questioning and evaluating evidence in order to reach logical conclusions."}, {"ar": "تقديم أنشطة إثرائية متنوعة ومبتكرة تنمي مهارات التقويم والإبداع والبحث، مثل: التجارب، والمسابقات العلمية، والنوادي الفكرية، وحل المشكلات الواقعية.", "en": "Offer varied, innovative enrichment activities that develop evaluation, creativity and research skills, such as experiments, science competitions, intellectual clubs and real-world problem solving."}, {"ar": "متابعة تنفيذ الأنشطة وتنمية التفكير والبحث والابتكار بانتظام من خلال أدوات تقويم نوعية (ملاحظة، وملف إنجاز، ومهام أداء) لقياس مستوى الإبداع والتحليل والتقويم لدى المتعلمين.", "en": "Regularly follow up the implementation of activities and the development of thinking, research and innovation using qualitative assessment tools (observation, portfolio, performance tasks) to measure learners' level of creativity, analysis and evaluation."}], "2-1-1-8": [{"ar": "تنفيذ برامج تعليمية وأنشطة صفية ولاصفية تستهدف تنمية مهارات التحكم في العواطف وضبط الانفعالات والتفاعل الإيجابي مع الآخرين.", "en": "Implement educational programs and classroom and extracurricular activities that develop skills of controlling emotions, regulating reactions and interacting positively with others."}, {"ar": "تهيئة بيئة صفية آمنة وتعاونية تشجع العمل الجماعي والمناقشة والحوار الفعال، ويسودها الاحترام المتبادل بين المتعلمين.", "en": "Create a safe, cooperative classroom environment that encourages teamwork, discussion and effective dialogue, in which mutual respect prevails among learners."}, {"ar": "دمج مهارات التواصل العاطفي والاجتماعي في الممارسات التعليمية اليومية عبر مواقف تعلم تعزز التعبير عن المشاعر وإدارتها بوعي واتزان.", "en": "Integrate emotional and social communication skills into daily teaching practice through learning situations that promote expressing and managing feelings with awareness and balance."}, {"ar": "تفعيل أنشطة تعلم تفاعلية متنوعة، مثل المسرح التربوي والمناقشات الجماعية ولعب الأدوار والمحاكاة لتنمية التعاطف والتفاهم المتبادل.", "en": "Activate varied interactive learning activities, such as educational theater, group discussions, role play and simulation, to develop empathy and mutual understanding."}, {"ar": "تنفيذ برامج إرشادية وتوعوية تُعنى بتنمية الذكاء العاطفي لدى المتعلمين وتدريبهم على التعامل الإيجابي مع المواقف الانفعالية.", "en": "Implement guidance and awareness programs concerned with developing learners' emotional intelligence and training them to deal positively with emotional situations."}, {"ar": "تحفيز المتعلمين على تبادل الأفكار واحترام وجهات النظر، وتعزيز قيم التسامح وقبول التنوع والتعاون البناء في بيئة التعلم.", "en": "Motivate learners to exchange ideas and respect viewpoints, and reinforce the values of tolerance, acceptance of diversity and constructive cooperation in the learning environment."}, {"ar": "توظيف استراتيجيات تربوية فعالة لتنمية مهارات الضبط الانفعالي والتفاعل الإيجابي في المواقف الصفية.", "en": "Use effective educational strategies to develop emotional-regulation skills and positive interaction in classroom situations."}, {"ar": "متابعة أثر البرامج والأنشطة بطرق مبتكرة لقياس مدى تحسن مهارات التحكم في العواطف والتواصل الإيجابي بين المتعلمين.", "en": "Follow up the impact of programs and activities in innovative ways to measure improvement in emotional-control skills and positive communication among learners."}], "2-1-1-9": [{"ar": "تنويع أساليب وأنشطة التعلم لتشمل الألعاب التعليمية وتمثيل الأدوار والتجارب العملية والقصص والرسوم والأفلام، بما يثير فضول المتعلمين ويزيد من متعتهم بالتعلم.", "en": "Diversify learning methods and activities to include educational games, role play, hands-on experiments, stories, drawings and films, arousing learners' curiosity and increasing their enjoyment of learning."}, {"ar": "تطبيق أساليب تحفيزية إيجابية متنوعة (الإشادة والثناء، والمكافآت الرمزية، والاحتفاء بالمنجزات) لرفع دافعية المتعلمين وتشجيعهم على المبادرة والمشاركة.", "en": "Apply varied positive motivational methods (praise and commendation, symbolic rewards, celebrating achievements) to raise learners' motivation and encourage initiative and participation."}, {"ar": "تهيئة بيئة تعلم آمنة ومحفزة يسودها الاحترام المتبادل والتقدير والثقة، وتدعم الشعور بالراحة والرفاه النفسي والاجتماعي للمتعلمين.", "en": "Create a safe, stimulating learning environment marked by mutual respect, appreciation and trust, supporting learners' sense of comfort and psychological and social well-being."}, {"ar": "تصميم أنشطة تعلم تراعي الميول والرغبات الفردية وتكشف عن اهتمامات المتعلمين وتشجعهم على البحث والاكتشاف.", "en": "Design learning activities that take individual inclinations and wishes into account, reveal learners' interests and encourage them to research and discover."}, {"ar": "تطبيق استراتيجيات تعلم تفاعلية تعتمد على الحوار والمناقشة وطرح الأسئلة والاستقصاء لتنمية حب التعلم وحب الاستطلاع.", "en": "Apply interactive learning strategies based on dialogue, discussion, questioning and inquiry to develop a love of learning and curiosity."}, {"ar": "متابعة دافعية المتعلمين واهتماماتهم من خلال ملاحظات صفية واستطلاعات رأي تقيس التحسن في تفاعلهم وفضولهم للتعلم.", "en": "Follow up learners' motivation and interests through classroom observations and opinion surveys that measure improvement in their engagement and curiosity to learn."}, {"ar": "تمكين المتعلمين من التعبير عن آرائهم وأفكارهم بثقة، وتقدير مبادراتهم، وتشجيعهم على دعم زملائهم والتعاون في تنفيذ الأنشطة.", "en": "Empower learners to express their opinions and ideas confidently, appreciate their initiatives, and encourage them to support peers and cooperate in carrying out activities."}, {"ar": "توظيف التقنية والوسائط المتعددة في تصميم أنشطة ممتعة ومشوقة تعزز الفضول والاكتشاف وتربط التعلم بمتعة التجربة والبحث الذاتي.", "en": "Use technology and multimedia in designing enjoyable, engaging activities that foster curiosity and discovery and connect learning with the pleasure of experimentation and self-directed research."}]};
